<div class="split-layout"><section class="stack"><article class="card"><div class="meta"><span><?= e($t['ho_ten']) ?> · <?= e($t['ngay_tao']) ?></span><?php badge($t['trang_thai']) ?></div><h2><?= e($t['tieu_de']) ?></h2><div class="prose"><?= nl2br(e($t['mo_ta'])) ?></div><div class="ticket-properties"><span>Ưu tiên <?php badge($t['uu_tien']) ?></span><span>Tài sản <strong><?= e($t['ten_may']??'Không chọn') ?></strong></span><span>Người xử lý <strong><?= e($t['handler']??'Chưa được gán') ?></strong></span><?php if($t['ngay_dong']): ?><span>Hoàn thành <strong><?= e($t['ngay_dong']) ?></strong></span><?php endif ?></div></article><section class="card"><h2>Lịch sử trao đổi</h2><?php if(!$comments): ?><p class="empty">Chưa có cập nhật từ bộ phận IT.</p><?php endif ?><?php foreach($comments as $c): ?><article class="comment"><span class="avatar small"><?= e(mb_substr($c['ho_ten'],0,1)) ?></span><div><div class="meta"><strong><?= e($c['ho_ten']) ?></strong><time><?= e($c['ngay_gui']) ?></time></div><p class="prose"><?= nl2br(e($c['noi_dung'])) ?></p></div></article><?php endforeach ?></section></section><?php if(user()['role']==='it_admin'): ?><aside class="stack"><section class="card"><h2>Xử lý yêu cầu</h2><form method="post" class="form-stack" id="ticket-update-form"><?php csrf_field() ?><input type="hidden" name="action" value="update"><?php select_field('nguoi_xu_ly','Người xử lý',[''=>'Chưa gán']+array_column($handlers,'ho_ten','id'),$t['nguoi_xu_ly']); select_field('trang_thai','Trạng thái',['new'=>'Mới','in_progress'=>'Đang xử lý','completed'=>'Hoàn thành'],$t['trang_thai']); ?><button id="update-ticket" class="button">Lưu cập nhật</button></form></section><section class="card"><h2>Thêm bình luận</h2><form method="post" class="form-stack" id="ticket-comment-form"><?php csrf_field() ?><input type="hidden" name="action" value="comment"><?php textarea_field('noi_dung','Nội dung phản hồi','',5000) ?><button id="comment-ticket" class="button">Gửi bình luận</button></form></section></aside><?php endif ?></div>
